function armsHeroEffect(id) {
  const C = B.armsIntegrated.CONFIG;
  const effects = {
    ihs: 'Смертельный удар требует на ' + C.ihs.join('/') + ' ярости меньше.',
    deflection: 'Вероятность парирования увеличивается на ' + Math.round(C.deflectionPerRank * 100) + '% за ранг.',
    imprend: 'Урон Кровопускания увеличивается на ' + C.impRend.map(x => Math.round(x * 100)).join('/') + '%.',
    impthunder: 'Удар грома требует на ' + C.impThunder.join('/') + ' ярости меньше.',
    deepwounds: 'Урон базовых Глубоких ран увеличивается на ' + C.deepWounds.totalOfAtk.map(x => Math.round(x * 100)).join('/') + '%. Второе кровотечение не добавляется.',
    twohand: 'Урон оружейных автоатак и способностей увеличивается на ' + Math.round(C.twoHandPerRank * 100) + '% за ранг. Не усиливает кровотечения и Удар грома.',
    impale: 'Критическая прибавка к урону способностей увеличивается на ' + Math.round(C.impalePerRank * 100) + '/' + Math.round(C.impalePerRank * 200) + '%. Не усиливает автоатаки и периодический урон.',
    sweeping: 'Оружейные удары дополнительно поражают вторую цель: до ' + C.sweeping.charges + ' ударов за ' + C.sweeping.turns + ' своих хода. Стоимость: ' + C.sweeping.rage + ' ярости; перезарядка: ' + C.sweeping.cd + ' ходов.'
  };
  return Object.prototype.hasOwnProperty.call(effects, id) ? effects[id] : 'Этот талант пока недоступен для изучения.';
}
